def fitbasis(extra_names, extra_funcs):
    best=None
    for w0 in np.linspace(0.2,6,40):
        def m(p):
            s=p[0]*np.cos(p[1]*t)+p[2]*np.sin(p[1]*t)+p[3]*v+p[4]*x+p[5]
            for i,f in enumerate(extra_funcs):
                s=s+p[6+i]*f
            return s
        p0=[1,w0,1,-1,-1,0]+[0]*len(extra_funcs)
        r=least_squares(lambda p: m(p)-y,p0)
        if best is None or r.cost<best[0].cost: best=(r,m)
    r,m=best
    print(extra_names, np.round(r.x,4), 'nmse', np.mean((m(r.x)-y)**2)/np.var(y))
    return r,m
fitbasis(['x^3','x^2','v^2','v|v|','x|x|'],[x**3,x**2,v**2,v*np.abs(v),x*np.abs(x)])
